  'praia-chefe-ponta-da-ressaca': ['cunha', 'seixo', 'espigao'],
  'praia-pocas-espelho': ['espigao', 'cunha', 'gemeas'],
  'praia-exp-ilhas-em-triangulo': ['seixo', 'espigao', 'bloco'],
